int flush_key_notification_policy(const struct km_event *c) {
    struct sk_buff *skb;
    int err;

    skb = alloc_skb(sizeof(struct key_mgmt_msg), GFP_KERNEL);
    if (!skb) {
        return -ENOBUFS;
    }

    // Initialize the header with the sequence and port ID from the event structure
    struct key_mgmt_msg *msg = skb_put(skb, sizeof(struct key_mgmt_msg));
    msg->sequence = c->sequence;
    msg->port_id = c->port_id;

    // Broadcast the message
    err = broadcast_key_message(skb);
    if (err < 0) {
        kfree_skb(skb);
        return err;
    }

    return 0;
}

int flush_key_notify_policy(const struct km_event *c)
{
    struct sk_buff *skb;
    int err;

    skb = alloc_skb(KEY_NOTIFY_POLICY_HLEN, GFP_ATOMIC);
    if (!skb) {
        return -ENOBUFS;
    }

    skb_put(skb, KEY_NOTIFY_POLICY_HLEN);
    skb_reset_transport_header(skb);

    /* Initialize the message header */
    skb->data[0] = c->seq;
    skb->data[1] = c->port_id;

    err = dev_broadcast(skb, NULL);
    if (err < 0) {
        kfree_skb(skb);
        return err;
    }

    return 0;
}

